use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { let args : Vec < String > = std :: env :: args () . collect () ; let base_path = if args . len () > 1 { PathBuf :: from (& args [1]) } else { PathBuf :: from ("../../") } ; let recursive = args . contains (& "--recursive" . to_string ()) ; println ! ("🚀 Starting ecosystem-wide declaration splitting") ; println ! ("📂 Base path: {}" , base_path . display ()) ; println ! ("🔄 Recursive: {}" , recursive) ; let start_time = Instant :: now () ; let mut config = crate :: config_macros :: GLOBAL_CONFIG . lock () . unwrap () . clone () ; config . wrapping = mkwrapping ! () ; let mut processed = 0 ; let mut errors = 0 ; if recursive { println ! ("🔍 Counting total crates...") ; let total_crates = count_crates (& base_path) ? ; println ! ("📊 Found {} crates to process" , total_crates) ; process_recursive (& base_path , & config , & mut processed , & mut errors , & start_time , Some (total_crates)) ? ; } else { if let Err (e) = process_crate (& base_path , & config , false) { println ! ("❌ Error processing {}: {}" , base_path . display () , e) ; errors += 1 ; } else { processed += 1 ; } } let total_time = start_time . elapsed () . as_secs_f64 () ; println ! ("✅ Ecosystem transformation complete!") ; println ! ("📊 Processed: {} crates in {:.1}m" , processed , total_time / 60.0) ; println ! ("❌ Errors: {} crates" , errors) ; println ! ("⚡ Average rate: {:.1} crates/min" , processed as f64 / (total_time / 60.0)) ; Ok (()) }
}